select session_id, title, create_time, update_time
from crm_ai_chat_session
where tenant_id = #{tenantId}
  and user_id = #{userId}
  and del_flag = '0'
order by update_time desc

select session_id, tenant_id, user_id, title, create_time, update_time, del_flag
from crm_ai_chat_session
where tenant_id = #{tenantId}
  and user_id = #{userId}
  and session_id = #{sessionId}
  and del_flag = '0'

mapper.insert:
insert into crm_ai_chat_session (
    session_id, tenant_id, user_id, title, create_time, update_time, del_flag
) values (
    #{sessionId}, #{tenantId}, #{userId}, #{title}, #{createTime}, #{updateTime}, #{delFlag}
