mapper.update:
update crm_ai_chat_session
set update_time = CURRENT_TIMESTAMP
, title = #{title}
where tenant_id = #{tenantId}
  and user_id = #{userId}
  and session_id = #{sessionId}
  and del_flag = '0'

update crm_ai_chat_session
set del_flag = '1', update_time = CURRENT_TIMESTAMP
where tenant_id = #{tenantId}
  and user_id = #{userId}
  and session_id = #{sessionId}
  and del_flag = '0'
